export default function App() {
  const [counterA, setCounterA] = useState(null);
  const [counterB, setCounterB] = useState(null);
  const [countA, setCountA] = useState(0);
  const [countB, setCountB] = useState(10);

  const handleInitA = () => {
    const nextCounter = createCounter(0);
    setCounterA(() => nextCounter);
    setCountA(0);
  };

  const handleInitB = () => {
    const nextCounter = createCounter(10);
    setCounterB(() => nextCounter);
    setCountB(10);
  };

  const handleIncrementA = () => {
    if (counterA) {
      setCountA(counterA());
    }
  };

  const handleIncrementB = () => {
    if (counterB) {
      setCountB(counterB());
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2>독립 상태 생성기</h2>

      <div style={{ marginBottom: '20px', padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h3>카운터 A (시작값: 0)</h3>
        <button onClick={handleInitA}>카운터 A 초기화/생성</button>
        {counterA && (
          <div style={{ marginTop: '10px' }}>
            <p>현재 값: <strong>{countA}</strong></p>
            <button onClick={handleIncrementA}>카운터 A 증가</button>
          </div>
        )}
      </div>

      <div style={{ padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h3>카운터 B (시작값: 10)</h3>
        <button onClick={handleInitB}>카운터 B 초기화/생성</button>
        {counterB && (
          <div style={{ marginTop: '10px' }}>
            <p>현재 값: <strong>{countB}</strong></p>
            <button onClick={handleIncrementB}>카운터 B 증가</button>
          </div>
        )}
      </div>
    </div>
  );
}
